{
  "steps": [
    {
      "title": "დაარეგულირე სიმაღლე",
      "text": "გამოსწიე ყვითელი ღილაკი სავარძლის ქვეშ და ისე დააყენე, რომ ჯდომისას მუხლები ბალიშების ქვეშ მჭიდროდ მოექცეს.",
      "focus": ["p6", "p5"],
      "avoid": ["p2"],
      "markers": [
        {"part": "p6", "label": "სიმაღლის მარეგულირებელი", "tone": "brand"}
      ],
      "arrows": [{"part": "p6", "type": "move", "dir": "toward"}],
      "tools": [],
      "warn": "ფოტოზე ორი ყვითელი დეტალია; სავარძლის ქვეშ მდებარეობის მიხედვით მარეგულირებლად შერჩეულია p6 და არა წონის ქინძისთავი p2. რეგულირება შეასრულე დაუტვირთავ სავარძელზე და დაჯდომამდე შეამოწმე მისი ჩაკეტვა."
    },
    {
      "title": "აირჩიე წონა",
      "text": "ყვითელი ქინძისთავი გადაიტანე სასურველ ფილაში და ბოლომდე ჩაარჭე.",
      "focus": ["p2"],
      "avoid": ["p6"],
      "markers": [
        {"part": "p2", "label": "წონის ამომრჩევი", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": "ფილების დასტაზე მდებარეობის მიხედვით წონის ამომრჩევად შერჩეულია p2. წონა შეცვალე მხოლოდ მაშინ, როცა ფილები სრულად დაშვებულია; შესაბამისი დატვირთვა ფოტოდან ვერ განისაზღვრება."
    },
    {
      "title": "მოკიდე სახელურს",
      "text": "ფეხზე მდგომმა მოკიდე ხელი მოხრილ ბოლოებთან, მხრებზე ოდნავ ფართოდ, ხელისგულები წინ.",
      "focus": ["p1"],
      "avoid": [],
      "markers": [
        {"part": "p1", "label": "მოჭიდება მოხრილ ბოლოებთან", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": null
    },
    {
      "title": "დაჯექი და დაფიქსირდი",
      "text": "სახელურით ხელში დაჯექი, ფეხები იატაკზე, მუხლები ბალიშების ქვეშ. მკერდი წინ, ზურგი სწორი.",
      "focus": ["p5", "p3", "p4", "p1"],
      "avoid": [],
      "markers": [
        {"part": "p5", "label": "სავარძელი", "tone": "brand"},
        {"part": "p3", "label": "მუხლი ბალიშის ქვეშ", "tone": "brand"},
        {"part": "p4", "label": "მუხლი ბალიშის ქვეშ", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": null
    },
    {
      "title": "ჩამოწიე მკერდამდე",
      "text": "იდაყვები ქვემოთ და უკან, სახელური მკერდის ზედა ნაწილამდე. ზემოთ ნელა აუშვი, 2 წამში.",
      "focus": ["p1"],
      "avoid": [],
      "markers": [
        {"part": "p1", "label": "ჩამოწიე კონტროლირებულად", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p1", "type": "move", "dir": "down"},
        {"part": "p1", "type": "move", "dir": "up"}
      ],
      "tools": [],
      "warn": "არ მოქაჩო ბიძგით და არ ჩამოიტანო სახელური კისრის უკან. 2 წამი ინსტრუქციის ტემპია და არა ფოტოდან დადასტურებული მონაცემი."
    }
  ],
  "unknown_parts": []
}
